-- ============================================================
-- 新日本名木100選 シードデータ
-- Supabase の SQL Editor で実行してください
-- ============================================================

-- Step 1: 緯度・経度を NULL 許可に変更（既存テーブルへのマイグレーション）
ALTER TABLE trees ALTER COLUMN latitude DROP NOT NULL;
ALTER TABLE trees ALTER COLUMN longitude DROP NOT NULL;

-- Step 2: 新日本名木100選 100件を投入
-- ※ 座標（latitude/longitude）は後で追加が必要です
-- ※ 幹周はメートル→センチメートルに変換済み
-- ※ 枯死・倒壊の樹木は description に記載


-- 完了確認
SELECT count(*) AS inserted, source_name FROM trees WHERE source_name = '新日本名木100選' GROUP BY source_name;
